  8→  var QUESTIONNAIRES_BY_ROLE = {
  9→    rider: {
 10→      route_deviation: [
 11→        { key: "expected_route", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 12→        { key: "was_route_agreed", label: "Did you and the driver agree to take a different route?", kind: "yes_no" },
 13→        { key: "asked_driver_to_stop", label: "Did you ask the driver to stop anywhere along the way?", kind: "yes_no" },
 14→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 15→      ],
 16→      no_show_charge: [
 17→        { key: "where_were_you", label: "Where were you when the trip was meant to start?", kind: "open" },
 18→        { key: "did_driver_contact_you", label: "Did the driver try to contact you?", kind: "yes_no" },
 19→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 20→      ]
 21→    },
 22→    driver: {
 23→      route_deviation: [
 24→        { key: "route_shown_to_driver", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 25→        { key: "route_agreed_with_rider", label: "Did you and the rider agree to take a different route?", kind: "yes_no" },
 26→        { key: "rider_requested_stop", label: "Did the rider ask you to stop anywhere along the way?", kind: "yes_no" },
 27→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 28→      ],
 29→      no_show_charge: [
 30→        { key: "driver_waiting_place", label: "Where did you wait, and for roughly how long?", kind: "open" },
 31→        { key: "driver_contacted_rider", label: "Did you try to call or message the rider?", kind: "yes_no" },
 32→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 33→      ]
 34→    }
 35→  };
 36→
 37→  var CATEGORIES_BY_ROLE = {
 38→    rider: [
 39→      { id: "route_deviation", label: "My trip went the wrong way" },
 40→      { id: "no_show_charge", label: "I was charged for a trip that did not happen" },
 41→      { id: "property_damage_mess", label: "Property damage or a mess left behind" },
 42→      { id: "safety_incident", label: "A safety incident" },
 43→      { id: "other", label: "Something else" }
 44→    ],
 45→    driver: [
 46→      { id: "route_deviation", label: "A question about the route I took" },
 47→      { id: "no_show_charge", label: "A no-show or waiting fee" },
 48→      { id: "property_damage_mess", label: "A cleaning fee or damage report" },
 49→      { id: "safety_incident", label: "A safety incident" },
 50→      { id: "other", label: "Something else" }
 51→    ]
 52→  };
 53→
 54→  var STATUS_HEADINGS = {
 55→    decided: "We have made a decision",
 56→    under_review: "Your case is still under review",
 57→    passed_to_support: "Your report has been passed to our support team",
 58→    needs_info: "We need a little more information"
 59→  };
 60→
 61→  var state = {
 62→    category: null,
 63→    tripId: null,
 64→    trips: [],
 65→    runId: null
 66→  };
 67→
 68→  // W30: request ownership. The trip list loads asynchronously, so only the newest
 69→  // request may render or land. Every load, category reset and trip Back bumps this
 70→  // epoch; a callback whose captured epoch no longer matches changes nothing.
 71→  var tripRequestEpoch = 0;
 72→
 73→  var stepCategory = document.getElementById("step-category");
 74→  var stepTrip = document.getElementById("step-trip");
 75→  var stepDetails = document.getElementById("step-details");
 76→  var outcomePanel = document.getElementById("outcome");
 77→  var categoryOptions = document.getElementById("category-options");
 78→  var tripOptions = document.getElementById("trip-options");
 79→  var questionList = document.getElementById("question-list");
 80→  var questionBoxes = document.getElementById("question-boxes");
 81→  var outcomeTitle = document.getElementById("outcome-title");
 82→  var outcomeReference = document.getElementById("outcome-reference");
 83→  var outcomeMessage = document.getElementById("outcome-message");
 84→  var outcomeQuestions = document.getElementById("outcome-questions");
 85→  var outcomeStatus = document.getElementById("outcome-status");
 86→
 87→  function element(tag, className, text) {
 88→    var node = document.createElement(tag);
 89→    if (className) {
 90→      node.className = className;
 91→    }
 92→    if (text !== undefined && text !== null) {
 93→      node.textContent = String(text);
 94→    }
 95→    return node;
 96→  }
 97→
 98→  function showError(id, message) {
 99→    var node = document.getElementById(id);
100→    node.textContent = message;
101→    node.hidden = false;
102→  }
103→
104→  function clearError(id) {
105→    var node = document.getElementById(id);
106→    node.textContent = "";
107→    node.hidden = true;
108→  }
109→
110→  function show(node) {
111→    node.hidden = false;
112→  }
113→
114→  function hide(node) {
115→    node.hidden = true;
116→  }
117→
118→  function request(method, path, body) {
119→    var options = { method: method };
120→    if (body !== undefined) {
121→      options.headers = { "Content-Type": "application/json" };
122→      options.body = JSON.stringify(body);
123→    }
124→    return fetch(path, options).then(function (response) {
125→      return response.json().then(function (payload) {
126→        if (!response.ok) {
127→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
128→          throw new Error(reason);
129→        }
130→        return payload;
131→      });
132→    });
133→  }
134→
135→  // ------------------------------------------------------------- page role
136→
137→  // The shell's own marker selects the questionnaire and the category copy. A
138→  // missing marker is the original rider shell; any other explicit value refuses
139→  // the whole page. This is demo copy selection, not authentication: the role is
140→  // never read from the URL, the document body or the fixed driver account.
141→  var formSteps = document.getElementById("form-steps");
142→  var role = formSteps.getAttribute("data-filed-by");
143→  if (role === null) {
144→    role = "rider";
145→  }
146→  var QUESTIONNAIRES = QUESTIONNAIRES_BY_ROLE[role];
147→  var CATEGORIES = CATEGORIES_BY_ROLE[role];
148→  if (role !== "rider" && role !== "driver") {
149→    showError("category-error",
150→      "This filing page could not be loaded. Please return to the help page and try again.");
151→    return;
152→  }
153→
154→  // ------------------------------------------------------------- step one
155→
156→  CATEGORIES.forEach(function (category) {
157→    var card = element("button", "option-card", category.label);
158→    card.type = "button";
159→    card.addEventListener("click", function () {
160→      state.category = category.id;
161→      Array.prototype.forEach.call(categoryOptions.children, function (child) {
162→        child.classList.remove("selected");
163→      });
164→      card.classList.add("selected");
165→      document.getElementById("category-next").disabled = false;
166→      // Changing the category resets everything downstream (R3 page side): the trip
167→      // list belongs to the category, so a trip picked for one category must never
168→      // survive a switch to another. The epoch bump abandons any in-flight load.
169→      tripRequestEpoch += 1;
170→      state.tripId = null;
171→      while (tripOptions.firstChild) {
172→        tripOptions.removeChild(tripOptions.firstChild);
173→      }
174→      document.getElementById("trip-next").disabled = true;
175→      clearError("trip-error");
176→      clearError("details-error");
177→      hide(stepTrip);
178→      hide(stepDetails);
179→    });
180→    categoryOptions.appendChild(card);
181→  });
182→
183→  document.getElementById("category-next").addEventListener("click", function () {
184→    clearError("category-error");
185→    hide(stepCategory);
186→    show(stepTrip);
187→    hide(stepDetails);
188→    loadTrips();
189→  });
190→
191→  // ------------------------------------------------------------- step two
192→
193→  // W30: bring the whole trip card on screen once the list has rendered. The card
194→  // is at most one screen tall, so aligning its top shows the Continue/Back bar
195→  // too. A response that arrives after the party pressed Back must not move the
196→  // page, so a hidden trip step is left alone.
197→  function landTripCard() {
198→    if (stepTrip.hidden) {
199→      return;
200→    }
201→    stepTrip.scrollIntoView({ block: "start" });
202→  }
203→
204→  function loadTrips() {
205→    var epoch = ++tripRequestEpoch;
206→    clearError("trip-error");
207→    var boxes = tripOptions;
208→    while (boxes.firstChild) {
209→      boxes.removeChild(boxes.firstChild);
210→    }
211→    state.tripId = null;
212→    document.getElementById("trip-next").disabled = true;
213→    boxes.appendChild(element("p", "loading", "Loading trips…"));
214→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
215→      .then(function (payload) {
216→        if (epoch !== tripRequestEpoch) {
217→          return;
218→        }
219→        while (boxes.firstChild) {
220→          boxes.removeChild(boxes.firstChild);
221→        }
222→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
223→        if (state.trips.length === 0) {
224→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
225→          landTripCard();
226→          return;
227→        }
228→        state.trips.forEach(function (trip) {
229→          var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
230→          var lines = [
231→            element("strong", null, trip.label),
232→            element("span", "trip-meta", meta)
233→          ];
234→          var charge = "";
235→          if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
236→            charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
237→              + (trip.charge_label ? " " + trip.charge_label : "");
238→          }
239→          var detail = element("span", "trip-meta", "");
240→          detail.textContent = "Trip " + trip.trip_id + charge;
241→          var card = element("button", "option-card trip-card");
242→          card.type = "button";
243→          lines.forEach(function (line) { card.appendChild(line); });
244→          card.appendChild(detail);
245→          card.addEventListener("click", function () {
246→            state.tripId = trip.trip_id;
247→            Array.prototype.forEach.call(boxes.children, function (child) {
248→              child.classList.remove("selected");
249→            });
250→            card.classList.add("selected");
251→            document.getElementById("trip-next").disabled = false;
252→          });
253→          boxes.appendChild(card);
254→        });
255→        landTripCard();
256→      })
257→      .catch(function (error) {
258→        if (epoch !== tripRequestEpoch) {
259→          return;
260→        }
261→        while (boxes.firstChild) {
262→          boxes.removeChild(boxes.firstChild);
263→        }
264→        showError("trip-error", error.message);
265→        landTripCard();
266→      });
267→  }
268→
269→  document.getElementById("trip-back").addEventListener("click", function () {
270→    // Back invalidates an outstanding load immediately: no new request has to
271→    // start for a late response to be stale.
272→    tripRequestEpoch += 1;
273→    show(stepCategory);
274→    hide(stepTrip);
275→    stepCategory.scrollIntoView({ block: "start" });
276→  });
277→
278→  document.getElementById("trip-next").addEventListener("click", function () {
279→    clearError("trip-error");
280→    hide(stepTrip);
281→    buildQuestions();
282→    show(stepDetails);
283→    window.scrollTo(0, 0);
284→  });
285→
286→  // --------------------------------------------------------- step three
287→
288→  function buildChoiceQuestion(question) {
289→    var field = element("div", "field");
290→    var label = element("label", null, question.label);
291→    // The choices container is a div, so a <label for> cannot point at it. The
292→    // question text reaches assistive tech via role="group" + aria-labelledby.
293→    label.id = "label-" + question.key;
294→    var choices = element("div", "choice-options");
295→    choices.id = "answer-" + question.key;
296→    choices.role = "group";
297→    choices.setAttribute("aria-labelledby", "label-" + question.key);
298→    var elaborate = element("textarea", "answer-input elaborate");
299→    elaborate.rows = 2;
300→    elaborate.setAttribute("data-elaborate-for", question.key);
301→    elaborate.placeholder = "Tell us more (optional)";
302→    elaborate.setAttribute("aria-label", "Tell us more: " + question.label);
303→    elaborate.hidden = true;
304→
305→    ["Yes", "No"].forEach(function (choice) {
306→      var button = element("button", "choice-button", choice);
307→      button.type = "button";
308→      button.setAttribute("data-choice", choice);
309→      button.setAttribute("aria-pressed", "false");
310→      button.dataset.questionKey = question.key;
311→      button.addEventListener("click", function () {
312→        if (!button.classList.contains("selected")) {
313→          elaborate.value = "";
314→        }
315→        Array.prototype.forEach.call(choices.children, function (sibling) {
316→          sibling.classList.remove("selected");
317→          sibling.setAttribute("aria-pressed", "false");
318→        });
319→        button.classList.add("selected");
320→        button.setAttribute("aria-pressed", "true");
321→        show(elaborate);
322→      });
323→      choices.appendChild(button);
324→    });
325→
326→    field.appendChild(label);
327→    field.appendChild(choices);
328→    field.appendChild(elaborate);
329→    return field;
330→  }
331→
332→  function buildQuestions() {
333→    while (questionList.firstChild) {
334→      questionList.removeChild(questionList.firstChild);
335→    }
336→    var questions = QUESTIONNAIRES[state.category] || [];
337→    questions.forEach(function (question) {
338→      if (question.kind === "yes_no") {
339→        questionList.appendChild(buildChoiceQuestion(question));
340→      } else if (question.kind === "open") {
341→        var field = element("div", "field");
342→        var label = element("label", null, question.label);
343→        label.htmlFor = "answer-" + question.key;
344→        var input = element("textarea", "answer-input");
345→        input.id = "answer-" + question.key;
346→        input.rows = 2;
347→        input.dataset.questionKey = question.key;
348→        field.appendChild(label);
349→        field.appendChild(input);
350→        questionList.appendChild(field);
351→      }
352→    });
353→  }
354→
355→  document.getElementById("details-back").addEventListener("click", function () {
356→    hide(stepDetails);
357→    show(stepTrip);
358→    loadTrips();
359→  });
360→
361→  document.getElementById("details-form").addEventListener("submit", function (event) {
362→    event.preventDefault();
363→    clearError("details-error");
364→    var description = document.getElementById("description").value;
365→    if (!description.trim()) {
366→      showError("details-error", "Please tell us what happened before sending.");
367→      return;
368→    }
369→    var amountText = document.getElementById("claim-amount").value.trim();
370→    var amount = null;
371→    if (amountText !== "") {
372→      amount = Number(amountText);
373→      if (!isFinite(amount) || amount < 0 || amount > 500) {
374→        showError("details-error", "The amount must be between 0 and 500 SGD.");
375→        return;
376→      }
377→    }
378→    var answers = {};
379→    (QUESTIONNAIRES[state.category] || []).forEach(function (question) {
380→      if (question.kind === "yes_no") {
381→        var selected = questionList.querySelector(
382→          '.choice-button.selected[data-question-key="' + question.key + '"]'
383→        );
384→        var elaborate = questionList.querySelector(
385→          'textarea[data-elaborate-for="' + question.key + '"]'
386→        );
387→        var choice = selected ? selected.dataset.choice : "";
388→        var elaboration = elaborate ? elaborate.value.trim() : "";
389→        answers[question.key] = choice
390→          ? (elaboration ? choice + " - " + elaboration : choice)
391→          : "";
392→      } else if (question.kind === "open") {
393→        var input = questionList.querySelector(
394→          'textarea[data-question-key="' + question.key + '"]'
395→        );
396→        answers[question.key] = input ? input.value : "";
397→      }
398→    });
399→
400→    var submit = document.getElementById("details-submit");
401→    submit.disabled = true;
402→    request("POST", "/api/disputes", {
403→      category: state.category,
404→      filed_by: role,
405→      trip_id: state.tripId,
406→      description: description,
407→      claim_amount_sgd: amount,
408→      answers: answers
409→    })
410→      .then(function (view) {
411→        renderOutcome(view);
412→      })
413→      .catch(function (error) {
414→        submit.disabled = false;
415→        showError("details-error", error.message);
416→      });
417→  });
418→
419→  // ------------------------------------------------------------- outcome
420→
421→  function renderOutcome(view) {
422→    hide(document.getElementById("form-steps"));
423→    show(outcomePanel);
424→    state.runId = view.run_id;
425→    outcomeTitle.textContent = STATUS_HEADINGS[view.status] || "Your dispute has been received";
426→    outcomeReference.textContent = view.dispute_id;
427→    outcomeMessage.textContent = view.message;
428→    hide(outcomeStatus);
429→    buildAnswerBoxes(view);
430→    window.scrollTo(0, 0);
431→  }
432→
433→  function buildAnswerBoxes(view) {
434→    while (questionBoxes.firstChild) {
435→      questionBoxes.removeChild(questionBoxes.firstChild);
436→    }
437→    var questions = Array.isArray(view.questions) ? view.questions : [];
438→    if (view.status !== "needs_info" || questions.length === 0) {
439→      hide(outcomeQuestions);
440→      return;
441→    }
442→    show(outcomeQuestions);
443→    questions.forEach(function (question, index) {
444→      var field = element("div", "field");
445→      var label = element("label", null, question);
446→      label.htmlFor = "reply-" + index;
447→      var input = element("textarea", "answer-input");
448→      input.id = "reply-" + index;
449→      input.rows = 2;
450→      // A round-two question the party has nothing to add to still needs an answer:
451→      // one click fills this box with the same sentence the run harness uses, so the
452→      // form can be completed without the party inventing words.
453→      var nothingMore = element("button", "nothing-more", "I have nothing more to add");
454→      nothingMore.type = "button";
455→      nothingMore.addEventListener("click", function () {
456→        input.value = "I have nothing more to add";
457→      });
458→      field.appendChild(label);
459→      field.appendChild(input);
460→      field.appendChild(nothingMore);
461→      questionBoxes.appendChild(field);
462→    });
463→  }
464→
465→  document.getElementById("answers-submit").addEventListener("click", function () {
466→    clearError("answers-error");
467→    var replies = [];
468→    var complete = true;
469→    Array.prototype.forEach.call(questionBoxes.querySelectorAll("textarea"), function (input) {
470→      var label = questionBoxes.querySelector('label[for="' + input.id + '"]');
471→      replies.push({ question: label ? label.textContent : "", answer: input.value });
472→      if (!input.value.trim()) {
473→        complete = false;
474→      }
475→    });
476→    if (!complete) {
477→      showError("answers-error", "Please answer each question before sending.");
478→      return;
479→    }
480→    var submit = document.getElementById("answers-submit");
481→    submit.disabled = true;
482→    outcomeStatus.textContent = "Sending your answers…";
483→    show(outcomeStatus);
484→    request("POST", "/api/disputes/" + encodeURIComponent(state.runId) + "/answers", {
485→      answers: replies
486→    })
487→      .then(function (view) {
488→        renderOutcome(view);
489→      })
490→      .catch(function (error) {
491→        submit.disabled = false;
